CREATE TABLE "categories" ("id" TEXT NOT NULL, "parent_id" TEXT NULL REFERENCES categories (id), "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL, "type" TEXT NOT NULL, "source_key" TEXT NULL, "condition_parts" TEXT NOT NULL, "position" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "series" ("id" TEXT NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "original_language" TEXT NULL, "creator" TEXT NULL, "published_volumes" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "series_titles" ("series_id" TEXT NOT NULL REFERENCES series (id) ON DELETE CASCADE, "language_code" TEXT NOT NULL, "title" TEXT NOT NULL, PRIMARY KEY ("series_id", "language_code"));
CREATE TABLE "items" ("id" TEXT NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "series_id" TEXT NULL REFERENCES series (id), "volume_number" INTEGER NULL, "original_language" TEXT NULL, "creator" TEXT NULL, "year" INTEGER NULL, "publisher" TEXT NULL, "image_path" TEXT NULL, "spine_color_value" INTEGER NULL, "rating" INTEGER NULL, "group_key" TEXT NULL, "source_key" TEXT NULL, "external_work_id" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "item_titles" ("item_id" TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE, "language_code" TEXT NOT NULL, "title" TEXT NOT NULL, PRIMARY KEY ("item_id", "language_code"));
CREATE TABLE "copies" ("id" TEXT NOT NULL, "item_id" TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE, "edition" TEXT NULL, "price_paid_cents" INTEGER NULL, "location" TEXT NULL, "barcode" TEXT NULL, "external_edition_id" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "copy_conditions" ("copy_id" TEXT NOT NULL REFERENCES copies (id) ON DELETE CASCADE, "part" TEXT NOT NULL, "condition" TEXT NOT NULL, PRIMARY KEY ("copy_id", "part"));
CREATE TABLE "preferences" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "pending_checks" ("id" TEXT NOT NULL, "kind" TEXT NOT NULL, "query" TEXT NOT NULL, "provisional_item_id" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));